         if (!$form) return;

         this.busy();

         let vals = $form.getValues();
         vals.fieldIDs = vals.fieldIDs.split(",");

         // Add new
         if (this.CurrentIndex == null)
            this.CurrentIndex = new ABIndex(vals, this.CurrentObject);

         // update values
